<svelte:options css="injected" />
<script lang="ts">
 import type {Snippet} from 'svelte';import Theme from '../../shared/Theme.svelte';import Icon from '../date-picker/DatePickerIcon.svelte';
 let {open,title,children,footer,onclose}:{open:boolean;title:string;children:Snippet;footer?:Snippet;onclose:()=>void}=$props();let dialog:HTMLDialogElement;let prior:HTMLElement|null=null;
 $effect(()=>{if(!dialog)return;if(open&&!dialog.open){const root=dialog.getRootNode();prior=(root instanceof ShadowRoot?root.activeElement:document.activeElement) as HTMLElement|null;dialog.showModal();}else if(!open&&dialog.open){dialog.close();prior?.focus();}});
</script>
<Theme><dialog bind:this={dialog} class="mc-ui-dialog-box ui-dialog" aria-label={title} oncancel={e=>{e.preventDefault();onclose();}}><div class="mc-ui-dialog-box__header"><span class="mc-ui-dialog-box__title">{title}</span><button class="mc-ui-dialog-box__headerbtn" aria-label="关闭对话框" onclick={onclose}><span class="mc-ui-dialog-box__close"><Icon name="clear"/></span></button></div><div class="mc-ui-dialog-box__body">{@render children()}</div>{#if footer}<div class="mc-ui-dialog-box__footer">{@render footer()}</div>{/if}</dialog></Theme>
<style>dialog.mc-ui-dialog-box.ui-dialog{--tv-DialogBox-padding:24px;--tv-DialogBox-vertical-padding:16px;--tv-DialogBox-bg-color:#fff;--tv-DialogBox-head-title-font-weight:600;--tv-DialogBox-head-title-font-size:18px;--tv-DialogBox-head-title-text-color:#191919;--tv-DialogBox-body-text-color:#595959;--tv-DialogBox-body-font-size:14px;--tv-DialogBox-close-icon-size:16px;position:fixed;inset:0;margin:auto;width:min(560px,calc(100vw - 32px));max-height:calc(100vh - 32px);overflow:auto;border:0;border-radius:var(--tv-DialogBox-border-radius,8px);padding:0;background:white;box-shadow:0 8px 32px #0003}dialog::backdrop{background:#0006}.mc-ui-dialog-box__close{color:var(--tv-DialogBox-close-icon-color,#808080)}</style>
